using System.Collections.Generic;
using System.Diagnostics;
using Unity.Cinemachine;
using UnityEngine;

namespace EasyFeedbacks
{

/// <summary>
/// Persistent owner of camera shakes generated by Easy Feedbacks.
/// Cinemachine still mixes and applies the underlying impulse events.
/// </summary>
[AddComponentMenu("Easy Feedbacks/Camera Shake Manager")]
[DisallowMultipleComponent]
public sealed class CameraShakeManager : MonoBehaviour
{
    [System.Flags]
    private enum PauseReason
    {
        None = 0,
        Handle = 1 << 0,
        Manager = 1 << 1,
        System = 1 << 2
    }

    [SerializeField, Min(0), Tooltip("Camera shake slots and reusable noise signals allocated when this manager wakes up.")]
    private int initialCapacity = 16;

    [SerializeField, Min(1), Tooltip("Hard limit for simultaneous camera shake layers owned by Easy Feedbacks.")]
    private int maximumCapacity = 64;

    private readonly List<ShakeVoice> allShakes = new List<ShakeVoice>();
    private readonly List<ShakeVoice> activeShakes = new List<ShakeVoice>();
    private readonly List<ShakeVoice> availableShakes = new List<ShakeVoice>();

    private bool allPaused;
    private bool systemPaused;
    private bool impulseCleanupPending;

    public static CameraShakeManager Instance { get; private set; }

    public int ActiveShakes => activeShakes.Count;
    public int AvailableShakes => availableShakes.Count;
    public int TotalShakes => allShakes.Count;
    public int MaximumCapacity => maximumCapacity;
    public bool AreAllShakesPaused => allPaused;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(this);
            return;
        }

        Instance = this;
        if (transform.parent != null)
        {
            Warn("CameraShakeManager must be a root object to persist between scenes. It was moved to the scene root at runtime.");
            transform.SetParent(null, true);
        }

        DontDestroyOnLoad(gameObject);

        NormalizeCapacity();
        EnsureStorageCapacity(initialCapacity);
        for (var i = 0; i < initialCapacity; i++)
        {
            availableShakes.Add(CreateShake());
        }

        SetSystemPaused(FeedbackService.AreAllPaused);
    }

    private void Update()
    {
        ReleaseFinishedShakes();
        RecycleExpiredImpulseEvents();
    }

    private void ReleaseFinishedShakes()
    {
        for (var i = activeShakes.Count - 1; i >= 0; i--)
        {
            var shake = activeShakes[i];
            var hasValidKick = InspectEvent(shake.Kick, out var kickExpired);
            var hasValidNoise = InspectEvent(shake.Noise, out var noiseExpired);
            if (kickExpired || noiseExpired)
            {
                impulseCleanupPending = true;
            }

            if (!hasValidKick && !hasValidNoise)
            {
                ReleaseShake(shake);
            }
        }
    }

    private void OnDisable()
    {
        if (Instance == this)
        {
            StopAllInternal(true);
            RecycleExpiredImpulseEvents();
        }
    }

    private void OnDestroy()
    {
        if (Instance == this)
        {
            StopAllInternal(true);
            RecycleExpiredImpulseEvents();
            Instance = null;
        }
    }

    private void OnValidate()
    {
        NormalizeCapacity();
    }

    public CameraShakeHandle Play(CameraShakeFeedbackEntry entry, FeedbackContext context)
    {
        if (entry == null || !entry.IsEnabled || entry.Profile == null)
        {
            return default;
        }

        return Play(
            entry.Profile,
            context.WorldPosition,
            entry.Profile.KickVector,
            entry.StrengthMultiplier * context.Intensity,
            entry.Loop,
            entry.NoiseDuration,
            entry.NoiseFadeIn,
            entry.NoiseFadeOut);
    }

    public CameraShakeHandle Play(
        CameraShakeProfile profile,
        Vector3 worldPosition,
        Vector3 cameraSpaceKickVector,
        float strength = 1f,
        bool loop = false,
        float noiseDuration = 0.35f,
        float noiseFadeIn = 0f,
        float noiseFadeOut = 0f)
    {
        if (profile == null || strength <= Mathf.Epsilon)
        {
            return default;
        }

        if (!isActiveAndEnabled)
        {
            Warn("CameraShakeManager cannot play while it is disabled.");
            return default;
        }

        var shake = AcquireShake();
        if (shake == null)
        {
            Warn($"CameraShakeManager reached Maximum Capacity ({maximumCapacity}). The camera shake was not played.");
            return default;
        }

        profile.Generate(
            worldPosition,
            cameraSpaceKickVector,
            strength,
            loop,
            noiseDuration,
            noiseFadeIn,
            noiseFadeOut,
            shake.NoiseSignal,
            out var kickEvent,
            out var noiseEvent);

        if (kickEvent == null && noiseEvent == null)
        {
            ReleaseShake(shake);
            return default;
        }

        shake.Kick.Capture(kickEvent);
        shake.Noise.Capture(noiseEvent);

        if (allPaused)
        {
            PauseShake(shake, PauseReason.Manager);
        }

        if (systemPaused)
        {
            PauseShake(shake, PauseReason.System);
        }

        return new CameraShakeHandle(this, shake.Id, shake.Generation);
    }

    public void Stop(CameraShakeHandle handle)
    {
        if (TryGetShake(handle, out var shake))
        {
            StopShake(shake, false);
            RecycleExpiredImpulseEvents();
        }
    }

    public void Pause(CameraShakeHandle handle)
    {
        if (TryGetShake(handle, out var shake))
        {
            PauseShake(shake, PauseReason.Handle);
        }
    }

    public void Resume(CameraShakeHandle handle)
    {
        if (TryGetShake(handle, out var shake))
        {
            ResumeShake(shake, PauseReason.Handle);
        }
    }

    public void StopAll(bool immediate = false)
    {
        StopAllInternal(immediate);
        RecycleExpiredImpulseEvents();
    }

    public void PauseAll()
    {
        if (allPaused)
        {
            return;
        }

        allPaused = true;
        for (var i = 0; i < activeShakes.Count; i++)
        {
            PauseShake(activeShakes[i], PauseReason.Manager);
        }
    }

    public void ResumeAll()
    {
        if (!allPaused)
        {
            return;
        }

        allPaused = false;
        for (var i = 0; i < activeShakes.Count; i++)
        {
            ResumeShake(activeShakes[i], PauseReason.Manager);
        }
    }

    public void Prewarm(int targetCapacity)
    {
        targetCapacity = Mathf.Clamp(targetCapacity, 0, maximumCapacity);
        EnsureStorageCapacity(targetCapacity);
        while (allShakes.Count < targetCapacity)
        {
            availableShakes.Add(CreateShake());
        }
    }

    internal void SetSystemPaused(bool paused)
    {
        if (systemPaused == paused)
        {
            return;
        }

        systemPaused = paused;
        for (var i = 0; i < activeShakes.Count; i++)
        {
            if (paused)
            {
                PauseShake(activeShakes[i], PauseReason.System);
            }
            else
            {
                ResumeShake(activeShakes[i], PauseReason.System);
            }
        }
    }

    internal bool IsHandleValid(CameraShakeHandle handle)
    {
        if (!TryGetShake(handle, out var shake))
        {
            return false;
        }

        if (HasAnyValidEvent(shake))
        {
            return true;
        }

        ReleaseShake(shake);
        return false;
    }

    private void StopAllInternal(bool immediate)
    {
        for (var i = activeShakes.Count - 1; i >= 0; i--)
        {
            StopShake(activeShakes[i], immediate);
        }
    }

    private ShakeVoice AcquireShake()
    {
        if (activeShakes.Count >= maximumCapacity)
        {
            ReleaseFinishedShakes();
            RecycleExpiredImpulseEvents();
            if (activeShakes.Count >= maximumCapacity)
            {
                return null;
            }
        }

        ShakeVoice shake;
        if (availableShakes.Count > 0)
        {
            var availableIndex = availableShakes.Count - 1;
            shake = availableShakes[availableIndex];
            availableShakes.RemoveAt(availableIndex);
        }
        else
        {
            shake = CreateShake();
        }

        unchecked
        {
            shake.Generation++;
            if (shake.Generation == 0)
            {
                shake.Generation = 1;
            }
        }

        shake.InUse = true;
        shake.Stopping = false;
        shake.PauseReasons = PauseReason.None;
        shake.ActiveListIndex = activeShakes.Count;
        activeShakes.Add(shake);
        return shake;
    }

    private ShakeVoice CreateShake()
    {
        var shake = new ShakeVoice(allShakes.Count);
        allShakes.Add(shake);
        return shake;
    }

    private void StopShake(ShakeVoice shake, bool immediate)
    {
        if (!shake.InUse)
        {
            return;
        }

        if (immediate || shake.IsPaused)
        {
            StopEvent(ref shake.Kick, true);
            StopEvent(ref shake.Noise, true);
            ReleaseShake(shake);
            return;
        }

        if (shake.Stopping)
        {
            return;
        }

        StopEvent(ref shake.Kick, false);
        StopEvent(ref shake.Noise, false);
        shake.Stopping = true;

        if (!HasAnyValidEvent(shake))
        {
            ReleaseShake(shake);
        }
    }

    private static void PauseShake(ShakeVoice shake, PauseReason reason)
    {
        if ((shake.PauseReasons & reason) != 0)
        {
            return;
        }

        var wasPaused = shake.IsPaused;
        shake.PauseReasons |= reason;
        if (wasPaused)
        {
            return;
        }

        PauseEvent(ref shake.Kick);
        PauseEvent(ref shake.Noise);
    }

    private static void ResumeShake(ShakeVoice shake, PauseReason reason)
    {
        if ((shake.PauseReasons & reason) == 0)
        {
            return;
        }

        shake.PauseReasons &= ~reason;
        if (shake.IsPaused)
        {
            return;
        }

        ResumeEvent(ref shake.Kick);
        ResumeEvent(ref shake.Noise);
    }

    private static void PauseEvent(ref EventToken token)
    {
        if (!IsEventValid(token) || token.Paused)
        {
            return;
        }

        token.Paused = true;
        token.PauseTime = CinemachineImpulseManager.Instance.CurrentTime;
        token.ChannelBeforePause = token.Event.Channel;
        token.EnvelopeBeforePause = token.Event.Envelope;

        var pausedEnvelope = token.Event.Envelope;
        pausedEnvelope.HoldForever = true;
        token.Event.Envelope = pausedEnvelope;
        token.Event.Channel = 0;
    }

    private static void ResumeEvent(ref EventToken token)
    {
        if (!MatchesCurrentEvent(token) || !token.Paused)
        {
            return;
        }

        var currentTime = CinemachineImpulseManager.Instance.CurrentTime;
        token.Event.StartTime += Mathf.Max(0f, currentTime - token.PauseTime);
        token.Event.Envelope = token.EnvelopeBeforePause;
        token.Event.Channel = token.ChannelBeforePause;
        token.Paused = false;
    }

    private static void StopEvent(ref EventToken token, bool immediate)
    {
        if (!IsEventValid(token))
        {
            return;
        }

        if (immediate)
        {
            token.Event.Channel = 0;
            token.Paused = false;
            return;
        }

        var stopTime = Mathf.Max(
            CinemachineImpulseManager.Instance.CurrentTime,
            token.Event.StartTime + 0.0001f);
        token.Event.Cancel(stopTime, false);
        token.Paused = false;
    }

    private static void ExpireEventImmediately(CinemachineImpulseManager.ImpulseEvent impulseEvent)
    {
        // Cinemachine only recycles events whose finite envelope has expired.
        // The channel is muted before this forced expiry, so no listener can observe it.
        impulseEvent.Channel = 0;
        impulseEvent.Envelope = new CinemachineImpulseManager.EnvelopeDefinition
        {
            SustainTime = 0.0001f
        };
        impulseEvent.Radius = 0f;
        impulseEvent.DissipationDistance = 0f;
        impulseEvent.StartTime = float.MinValue;
    }

    private static bool HasAnyValidEvent(ShakeVoice shake)
    {
        return IsEventValid(shake.Kick) || IsEventValid(shake.Noise);
    }

    private static bool IsEventValid(EventToken token)
    {
        return MatchesCurrentEvent(token) && !token.Event.Expired;
    }

    private static bool InspectEvent(EventToken token, out bool expired)
    {
        expired = false;
        if (!MatchesCurrentEvent(token))
        {
            return false;
        }

        expired = token.Event.Expired;
        return !expired;
    }

    private static bool MatchesCurrentEvent(EventToken token)
    {
        return token.Event != null
               && token.SignalSource != null
               && ReferenceEquals(token.Event.SignalSource, token.SignalSource);
    }

    private bool TryGetShake(CameraShakeHandle handle, out ShakeVoice shake)
    {
        shake = null;
        var shakeId = handle.ShakeId;
        if (!ReferenceEquals(handle.Owner, this)
            || handle.Generation == 0
            || shakeId < 0
            || shakeId >= allShakes.Count)
        {
            return false;
        }

        var candidate = allShakes[shakeId];
        if (!candidate.InUse || candidate.Generation != handle.Generation)
        {
            return false;
        }

        shake = candidate;
        return true;
    }

    private void ReleaseShake(ShakeVoice shake)
    {
        if (!shake.InUse)
        {
            return;
        }

        var activeIndex = shake.ActiveListIndex;
        var lastIndex = activeShakes.Count - 1;
        var lastShake = activeShakes[lastIndex];
        activeShakes[activeIndex] = lastShake;
        lastShake.ActiveListIndex = activeIndex;
        activeShakes.RemoveAt(lastIndex);

        impulseCleanupPending |= DetachEvent(ref shake.Kick);
        impulseCleanupPending |= DetachEvent(ref shake.Noise);
        shake.Reset();
        availableShakes.Add(shake);
    }

    private static bool DetachEvent(ref EventToken token)
    {
        if (!MatchesCurrentEvent(token))
        {
            return false;
        }

        token.Event.Channel = 0;
        token.Event.SignalSource = null;
        ExpireEventImmediately(token.Event);
        return true;
    }

    private void RecycleExpiredImpulseEvents()
    {
        if (!impulseCleanupPending)
        {
            return;
        }

        impulseCleanupPending = false;
        // A zero channel mask skips signal evaluation while Cinemachine prunes and recycles
        // expired events. Active Easy Feedbacks and third-party impulses remain untouched.
        CinemachineImpulseManager.Instance.GetImpulseAt(
            Vector3.zero,
            false,
            0,
            out _,
            out _);
    }

    private void EnsureStorageCapacity(int targetCapacity)
    {
        targetCapacity = Mathf.Clamp(targetCapacity, 0, maximumCapacity);
        if (allShakes.Capacity < targetCapacity)
        {
            allShakes.Capacity = targetCapacity;
        }

        if (activeShakes.Capacity < targetCapacity)
        {
            activeShakes.Capacity = targetCapacity;
        }

        if (availableShakes.Capacity < targetCapacity)
        {
            availableShakes.Capacity = targetCapacity;
        }
    }

    private void NormalizeCapacity()
    {
        maximumCapacity = Mathf.Max(1, maximumCapacity);
        initialCapacity = Mathf.Clamp(initialCapacity, 0, maximumCapacity);
    }

    [Conditional("UNITY_EDITOR"), Conditional("DEVELOPMENT_BUILD")]
    private static void Warn(string message)
    {
        UnityEngine.Debug.LogWarning(message);
    }

    private sealed class ShakeVoice
    {
        public readonly int Id;
        public uint Generation;
        public bool InUse;
        public bool Stopping;
        public int ActiveListIndex;
        public PauseReason PauseReasons;
        public EventToken Kick;
        public EventToken Noise;
        public readonly NoiseShakeSignal NoiseSignal = new NoiseShakeSignal();

        public bool IsPaused => PauseReasons != PauseReason.None;

        public ShakeVoice(int id)
        {
            Id = id;
            ActiveListIndex = -1;
        }

        public void Reset()
        {
            InUse = false;
            Stopping = false;
            ActiveListIndex = -1;
            PauseReasons = PauseReason.None;
            Kick.Reset();
            Noise.Reset();
            NoiseSignal.Reset();
        }
    }

    private struct EventToken
    {
        public CinemachineImpulseManager.ImpulseEvent Event;
        public ISignalSource6D SignalSource;
        public bool Paused;
        public float PauseTime;
        public int ChannelBeforePause;
        public CinemachineImpulseManager.EnvelopeDefinition EnvelopeBeforePause;

        public void Capture(CinemachineImpulseManager.ImpulseEvent impulseEvent)
        {
            Event = impulseEvent;
            SignalSource = impulseEvent != null ? impulseEvent.SignalSource : null;
            Paused = false;
            PauseTime = 0f;
            ChannelBeforePause = 0;
            EnvelopeBeforePause = default;
        }

        public void Reset()
        {
            Event = null;
            SignalSource = null;
            Paused = false;
            PauseTime = 0f;
            ChannelBeforePause = 0;
            EnvelopeBeforePause = default;
        }
    }
}
}
